#![allow(unused)]
use vstd::prelude::*;

verus! {

    /// Given three 32‐bit signed integers a, b, c,
    /// returns 1, 2, or 3 according to how many of them are equal:
    ///   • 3 if and only if all three are the same,
    ///   • 2 if and only if exactly two of them are the same,
    ///   • 1 if and only if all three are pairwise distinct.
    /// We also ensure the result is between 0 and 3 (0 is never produced).
    #[verifier(publish)]
    fn count_equal_numbers(a: i32, b: i32, c: i32) -> (count: i32)
        ensures  0 <= count && count <= 3
        ensures  (count == 3) == (a == b && b == c)
        ensures  (count == 2) == (
                      (a == b && a != c)
                   || (a == c && a != b)
                   || (b == c && b != a)
                  )
        ensures  (count == 1) == (a != b && b != c && a != c)
    {
        if a == b && b == c {
            // all three equal
            3
        } else if a == b || a == c || b == c {
            // exactly two equal
            2
        } else {
            // all distinct
            1
        }
    }

    proof fn test_count_equal_numbers() {
        // Some basic sanity checks:
        assert!(count_equal_numbers(5,5,5) == 3);
        assert!(count_equal_numbers(7,7,8) == 2);
        assert!(count_equal_numbers(7,8,7) == 2);
        assert!(count_equal_numbers(8,7,7) == 2);
        assert!(count_equal_numbers(1,2,3) == 1);
    }
}